import React, { useMemo, useRef } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
} from '../remotionShim';
import { noise2D } from "@remotion/noise";

{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type DecayCardProps = Record<string, any>;

const DecayCard: React.FC<DecayCardProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 10,
  cardImage = "https://picsum.photos/600/800?grayscale",
  cardTitle = "The Decay",
  cardSubtitle = "Simulation",
  accentColor = "#ffffff",
  distortionIntensity = 200,
  movementSpeed = 1.5,
  cardWidth = 400,
  cardHeight = 550,
  fontSize = 42,
}) => {
  // Load Fonts
  useFontLoader(["Playfair Display", "Inter"]);

  const frame = useCurrentFrame();
  const { width: canvasWidth, height: canvasHeight } = useVideoConfig();

  // Create unique IDs for filters to prevent conflicts if multiple instances exist
  const uniqueId = useMemo(() => `filter-${Math.random().toString(36).substr(2, 9)}`, []);

  // -- PHYSICS SIMULATION --
  // We simulate the "cursor" movement using Perlin noise for organic motion.
  // The original code used mouse coordinates; here we generate deterministic "virtual cursor" coordinates.
  
  const noiseSeedX = "cursor-x-movement";
  const noiseSeedY = "cursor-y-movement";
  
  // Calculate cursor position at current frame (t) and previous frame (t-1) to determine velocity
  const getCursorPos = (f: number) => {
    // Slow down the frame input for the noise function to get smooth, wandering movement
    const t = f * 0.005 * movementSpeed;
    
    // Map noise (-1 to 1) to screen coordinates with some overscan
    // The "cursor" wanders around the center of the screen
    const x = (canvasWidth / 2) + noise2D(noiseSeedX, t, 0) * (canvasWidth * 0.4);
    const y = (canvasHeight / 2) + noise2D(noiseSeedY, t, 0) * (canvasHeight * 0.4);
    return { x, y };
  };

  const currentCursor = getCursorPos(frame);
  const prevCursor = getCursorPos(frame - 2); // Use frame-2 to exaggerate speed for effect

  // Calculate "Velocity" (distance travelled between frames)
  const dist = Math.hypot(
    currentCursor.x - prevCursor.x,
    currentCursor.y - prevCursor.y
  );

  // Map velocity to displacement scale (faster movement = more distortion)
  // We clamp and smooth this value
  const displacementScale = interpolate(
    dist,
    [0, 20], // Input range: speed pixels per 2 frames
    [0, distortionIntensity], // Output range: displacement scale
    { extrapolateRight: "clamp" }
  );

  // -- CARD TRANSFORMS --
  // The card tilts and moves towards the cursor. 
  // In the original, this was a lerp. Here, we map the noise position directly to transforms.
  
  const rotateZ = interpolate(
    currentCursor.x,
    [0, canvasWidth],
    [-10, 10], // Rotate between -10 and 10 degrees based on X position
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const translateX = interpolate(
    currentCursor.x,
    [0, canvasWidth],
    [-80, 80], // Translate X based on cursor X
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const translateY = interpolate(
    currentCursor.y,
    [0, canvasHeight],
    [-80, 80], // Translate Y based on cursor Y
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Container simulating the 'content' div with transforms */}
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          position: "relative",
          transform: `translate3d(${translateX}px, ${translateY}px, 0) rotateZ(${rotateZ}deg)`,
          // Using standard CSS transition for smoother playback if needed, 
          // but Remotion updates every frame so 'transition: none' is usually best for frame-perfect rendering.
          transition: "none", 
          willChange: "transform",
        }}
      >
        {/* SVG Layer */}
        <svg
          viewBox={`0 0 ${cardWidth} ${cardHeight}`}
          style={{
            width: "100%",
            height: "100%",
            position: "absolute",
            top: 0,
            left: 0,
            overflow: "visible",
          }}
        >
          <defs>
            <filter id={uniqueId}>
              {/* Turbulence creates the noise pattern for the displacement */}
              <feTurbulence
                type="turbulence"
                baseFrequency="0.015"
                numOctaves="5"
                seed="4"
                stitchTiles="stitch"
                result="turbulence"
              />
              {/* DisplacementMap uses the turbulence to distort the source image */}
              {/* 'scale' is driven by our calculated velocity */}
              <feDisplacementMap
                in="SourceGraphic"
                in2="turbulence"
                scale={displacementScale}
                xChannelSelector="R"
                yChannelSelector="B"
              />
            </filter>
          </defs>

          {/* The Image */}
          <image
            href={cardImage}
            x="0"
            y="0"
            width={cardWidth}
            height={cardHeight}
            preserveAspectRatio="xMidYMid slice"
            filter={`url(#${uniqueId})`}
          />
        </svg>

        {/* Text Content Layer - Overlay */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            textAlign: "center",
            width: "80%",
            zIndex: 10,
            pointerEvents: "none",
            mixBlendMode: "difference", // Cool blending effect often seen in these styles
          }}
        >
          <h1
            style={{
              fontFamily: "Playfair Display, serif",
              fontSize: `${fontSize}px`,
              margin: 0,
              color: accentColor,
              lineHeight: 1,
              fontWeight: 700,
              letterSpacing: "-0.02em",
            }}
          >
            {cardTitle}
          </h1>
          {cardSubtitle && (
            <p
              style={{
                fontFamily: "Inter, sans-serif",
                fontSize: `${fontSize * 0.35}px`,
                marginTop: "10px",
                color: accentColor,
                opacity: 0.8,
                textTransform: "uppercase",
                letterSpacing: "0.1em",
                fontWeight: 600,
              }}
            >
              {cardSubtitle}
            </p>
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DecayCard;